import sys

def main():
    data = sys.stdin.read().split()
    m = int(data[0])
    pos = 1
    idx = {}
    parent = []
    emails = []
    names = []

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for _ in range(m):
        nm = data[pos]
        c = int(data[pos + 1])
        es = data[pos + 2:pos + 2 + c]
        pos += 2 + c
        first = -1
        for e in es:
            if e not in idx:
                idx[e] = len(parent)
                parent.append(len(parent))
                emails.append(e)
                names.append(nm)
            i = idx[e]
            if first < 0:
                first = i
            else:
                a, b = find(first), find(i)
                if a != b:
                    parent[a] = b
    groups = {}
    for i in range(len(emails)):
        groups.setdefault(find(i), []).append(i)
    out = []
    for mem in groups.values():
        es = sorted(emails[i] for i in mem)
        out.append((es[0], names[mem[0]], es))
    out.sort()
    print('\n'.join(nm + ' ' + ' '.join(es) for _, nm, es in out))

